def claude_bin(bin=CLAUDE_BIN):
    "Absolute path to the `claude` binary, or a `FileNotFoundError` that says how to get one."
    if (p := shutil.which(bin)): return p
    raise FileNotFoundError(
        f'{bin!r} is not on $PATH. Install Claude Code (https://claude.com/claude-code) and run '
        f'`{bin} /login`. rishi drives it as a subprocess and never reads your credentials.')

def claude_model(model=None, dflt=opus5):
    "Turn a `CLAUDE_MODELS` key such as `'opus5'` into its model id, pass other names through, and return `dflt` for an empty name."
    m = (model or '').strip()
    return CLAUDE_MODELS.get(m, m) if m else dflt

def claude_fallback(models):
    "Resolve a list or comma-separated string of models, as `claude_model` does, into the value `--fallback-model` takes."
    ms = models.split(',') if isinstance(models, str) else listify(models)
    return ','.join(x for m in ms if (x := claude_model(m, dflt='')))

@lru_cache
def claude_version(bin=CLAUDE_BIN):
    "Return the installed Claude Code version, cached per binary, or llmsurgery's pinned version when it cannot be read."
    try: out = subprocess.run([claude_bin(bin), '--version'], stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=30).stdout
    except Exception: out = ''
    m = re.search(r'\d+\.\d+\.\d+', out)
    return m.group(0) if m else ant.CC_VERSION

def sess_entrypoint(p, mx=50):
    "Return a transcript's `entrypoint`, if present in its first `mx` records."
    try:
        with p.open() as f:
            for i, l in enumerate(f):
                if i >= mx: return None
                try: rec = json.loads(l)
                except Exception: continue
                if (e := rec.get('entrypoint')): return e
    except OSError: return None
    return None

def prune_sessions(cwd=None, keep=0, age=None, entrypoint=CLAUDE_ENTRYPOINT):
    "Delete the transcripts rishi filed under `cwd`, sparing the newest `keep` and any younger than `age` seconds, and return the deleted paths."
    d = ant.sess_dir(cwd or CLAUDE_WORK_DIR)
    if not d.is_dir(): return []
    fs = sorted(d.glob('*.jsonl'), key=lambda p: p.stat().st_mtime, reverse=True)
    out, now = [], time.time()
    for p in fs[keep:]:
        if age is not None and now - p.stat().st_mtime < age: continue
        if sess_entrypoint(p) != entrypoint: continue
        p.unlink(missing_ok=True)
        out.append(p)
    return out


def norm_claude_usage(u, model=None, cost=None):
    "Convert Claude Code's usage block to a rishi usage dict, counting cache reads and writes as prompt tokens and keeping thinking tokens."
    if not u: return {}
    read, made = u.get('cache_read_input_tokens') or 0, u.get('cache_creation_input_tokens') or 0
    pt, ct = (u.get('input_tokens') or 0) + read + made, u.get('output_tokens') or 0
    res = {'prompt_tokens': pt, 'completion_tokens': ct, 'total_tokens': pt + ct, 'cached_tokens': read,
           'cache_creation_tokens': made, 'cost': cost or 0.0, 'model': model}
    if (th := (u.get('output_tokens_details') or {}).get('thinking_tokens')) is not None: res['reasoning_tokens'] = th
    return res

ABORTED = ('aborted_streaming', 'aborted')
TOOL_PARSE_ERR = "The model's tool call could not be parsed"   #: Claude Code's error result when it cannot read a call, even after its own retry
_status_re = re.compile(r'\b(\d{3})\b')

class ClaudeError(RuntimeError):
    "A failed Claude Code turn: what it said, the status behind it, the raw result, what it cost, and whether `max_budget_usd` stopped it."
    def __init__(self, msg, status=None, raw=None, usage=None, budget=False):
        self.status, self.raw, self.usage, self.budget = status, raw, usage or {}, budget
        super().__init__(msg)

def claude_status(d):
    "The HTTP status behind a failed result: what Claude Code reported, else one read out of the text."
    if (s := d.get('api_error_status')):
        try: return int(s)
        except (TypeError, ValueError): pass
    m = _status_re.search(f"{d.get('result') or ''} {d.get('subtype') or ''}")
    return int(m.group(1)) if m else None

def claude_tool_use(b, sdk):
    "Convert a `ToolUseBlock` to a plain record, else return `None`."
    if not isinstance(b, getattr(sdk, 'ToolUseBlock', ())): return None
    name = getattr(b, 'name', '') or ''
    server = name.split('__')[1] if name.startswith('mcp__') and name.count('__') >= 2 else ''
    return {'id': getattr(b, 'id', '') or '', 'name': name, 'server': server,
            'input': getattr(b, 'input', None) or {}}

def norm_claude(d, model=None, asked=False, tags=True):
    "Convert a Claude Code result to a rishi `Resp`, reading `<tool_call>` tags from the text when `tags` and flagging an unreadable call for one resend unless `asked`."
    if d.get('is_error') and d.get('terminal_reason') not in ABORTED:
        bad = TOOL_PARSE_ERR in (d.get('result') or '')
        if bad and not asked: return Resp({'role': 'assistant', 'content': d['result'], 'tool_parse_failed': True,
                                           'usage': norm_claude_usage(d.get('usage'), model, d.get('cost'))})
        use = norm_claude_usage(d.get('usage'), model, d.get('cost')) or ({'cost': d['cost'], 'model': model} if d.get('cost') else {})
        if (budget := d.get('subtype') == 'error_max_budget_usd'):   # the run was paid for: the cost goes with the error
            raise ClaudeError(f"claude stopped by its budget: it spent ${d.get('cost') or 0:.2f}, past max_budget_usd", status=None, raw=d, usage=use, budget=True)
        raise ClaudeError(f"claude failed: {d.get('result') or d.get('subtype')}{' (no resend left)' if bad else ''}",
                          status=claude_status(d), raw=d, usage=use)
    text, th = split_think(d.get('result') or '')
    text, tcs, failed = parse_tool_tags_ex(text) if tags else (text, [], False)
    res = {'role': 'assistant', 'content': text}
    if failed: res['tool_parse_failed'] = True   # the loop asks for the call again instead of ending on the prose
    if th: res['channels'] = {'thought': th}
    # tools Claude Code ran itself. Not `tool_calls`: nothing here is waiting on rishi to answer it.
    if (ran := d.get('server_tools')): res.setdefault('channels', {})['server_tools'] = ran
    if tcs: res['tool_calls'] = tcs
    res['usage'] = norm_claude_usage(d.get('usage'), model, d.get('cost'))
    return Resp(res)
INTERRUPT_WAIT = 5
CONT_PROMPT = 'The tool results are in. Continue your answer.'
STALL_PROMPT = 'Your last reply was cut off. Continue it from exactly where it stopped, repeating nothing.'
STALL_TIMEOUT = 240   #: seconds Claude Code may send nothing, not even a stream event, before the turn is ended and tried once more

class ClaudeStall(TimeoutError):
    "Claude Code sent nothing for the chat's `timeout` seconds."

class ClaudeDeadline(TimeoutError):
    "A call outran its `deadline`. `elapsed` is the seconds it ran. `stopped` is True when the SDK stream closed within `CLOSE_WAIT`; when False the call may still finish and spend, and the caller must assume it does."
    def __init__(self, elapsed, stopped):
        self.elapsed, self.stopped = elapsed, stopped
        super().__init__(f'Claude Code was still working after {elapsed:.1f}s, the deadline; ' +
                         ('its stream is closed' if stopped else 'its stream did not close in time, so the call may still finish and spend'))

