class ClaudeChat(RishiToolLoop, Chat):
    "A `Chat` that drives your Claude Code installation through the Claude Agent SDK."
    _runtime = 'claude'
    _media_note = ("this Claude Code chat cannot carry a picture or a document: it is stateless and has "
                   "no transcript to file, so the conversation goes as one text prompt, which has nowhere "
                   "to put one. Keep the default `stateful=True`, leave `transcript=True`, or use "
                   "`rishi.remote`/`rishi.litert`.")
    mk_content, mk_msg, mk_msgs = staticmethod(mk_claude_content), staticmethod(mk_claude_msg), staticmethod(mk_claude_msgs)
    local, _ctx_live = False, 0
    _nat_busy, _nat_end, _nat_ran, _session_effort, _claim_wait = 0, float('-inf'), False, None, 2.
    _spare = 0   # retries this wire call has left. See `_turn_opts`

    #: Claude Code takes an effort grade and nothing else a caller can turn
    _opt_map = {}
    _opt_skip = ('temp', 'top_k', 'top_p', 'seed', 'max_output_tokens', 'think',
                 'api_key', 'base_url')

    def __init__(self, model=None, *, runtime=None, model_path=None, opts=None,
                 permission_mode='auto',    # Claude Code's gate on its *own* tools. Yours are rishi's
                 claude_tools=None,         # Claude Code's own tools, allowlisted. None -> none at all when this chat carries tools, its default set when it carries none
                 claude_disallowed=CLAUDE_DISALLOWED,   # Claude Code tools it may never use
                 claude_server_tools=(),    # its web tools, which run on its side and never reach rishi's loop
                 mcp_servers=None,          # MCP servers to declare. None -> none at all. See `The wire`
                 mcp_tools=None,            # which of their tools to allow. None -> every tool of every server named
                 strict_mcp_config=False,   # refused outright where an enterprise MCP config exists
                 workspace=None,            # directory Claude Code works in. None -> `CLAUDE_WORK_DIR`. See `_cwd`
                 fallback=None,             # model, or models tried in order, for when this one is overloaded or retired
                 cleanup=True,              # remove the transcripts this chat filed when it closes. See `prune_sessions`
                 bare=True,                 # answer as a model: no CLAUDE.md, skills, plugins or hooks
                 stateful=True,             # keep one Claude Code session per chat. See `_connect`
                 transcript=True,           # file the conversation as records rather than prose. See `_file_sess`
                 api_key=False,             # False blanks `ANTHROPIC_API_KEY` in the subprocess; True lets it through. See `_opts`
                 max_buffer=MAX_BUFFER,     # the SDK's stdout cap, in bytes
                 bin=CLAUDE_BIN, settings=None,
                 timeout=STALL_TIMEOUT,     # seconds of silence before the turn is ended and tried once more. See `Silence`
                 on_stall=None,             # called with a status note when that happens. None -> `warnings.warn`
                 timeout_hint=None,         # how a caller raises `timeout`, named in the error. None -> `ClaudeChat(timeout=SECONDS)`
                 **kw):                     # portable options; see `urai.ChatOpts`
        o = ChatOpts.create(opts, **kw)
        self.model_id = claude_model(split_runtime(model)[1])
        self._set_tools(o.tools)
        self.effort = o.effort or None      # 'low'/'medium'/'high'/'xhigh'/'max'
        store_attr('permission_mode,claude_tools,claude_disallowed,claude_server_tools,workspace,'
                   'fallback,cleanup,bare,bin,timeout,on_stall,timeout_hint,settings,api_key,max_buffer,'
                   'mcp_servers,mcp_tools,strict_mcp_config')
        self.opts_ = dict(o.extra)          # anything else, straight through to the SDK
        self.stateful = stateful
        self.transcript = bool(transcript)
        self.client = self._last_res = None
        self._stale = False             # a cancelled turn leaves the transcript and `hist` disagreeing
        self._ctx_live = 0              # occupancy the session last reported. See `token_count`
        self._sent = 0                  # how much of `hist` the live session has seen
        self._nonce = uuid.uuid4().hex  # this chat's salt for a session id. See `_file_sess`
        self._filed = []                # the transcripts it wrote, its own to remove. See `_sweep`
        self._nat_uses, self._nat_missed, self._errlog = [], [], []   # native calls seen but not answered, answered but not seen, and Claude Code's stderr
        self.ctx_limit, self._ctx_tokens = o.ctx or None, 0
        self._setup(model, o)

    @property
    def in_session_mode(self):
        "Does this chat drive one live session, rather than a fresh `query` per turn?"
        return self.stateful

    @property
    def _media_ok(self):
        "A live session and a filed transcript both carry content blocks. A text prompt cannot."
        return self.in_session_mode or self.transcript

    @property
    def _cwd(self):
        "The working directory and transcript location."
        d = Path(self.workspace).expanduser() if self.workspace else CLAUDE_WORK_DIR
        return d.resolve()

    @property
    def tool_channel(self):
        "Where this chat's tool schemas travel: the prompt (`'tags'`), or rishi's in-process MCP server (`'native'`)."
        return self.opts.tool_mode or 'tags'   # urai's portable name for the same question

    @property
    def _native(self):
        "Do rishi's tools reach Claude through its own MCP server this turn?"
        return self.tool_channel == 'native' and bool(self.toolspecs)

    @property
    def _tool_busy(self):
        "Is a native tool running, or did one finish less than `timeout` seconds ago? The stall timer waits for it."
        return self._native and (bool(self._nat_busy) or time.monotonic() - self._nat_end < self.timeout)

    @property
    def mcp_toolnames(self):
        "The MCP tools this chat allows. Every tool of every server it named, unless told otherwise."
        if self.mcp_tools is not None: return list(self.mcp_tools)
        return [f'mcp__{name}' for name in (self.mcp_servers or {})]

    @property
    def token_count(self):
        "What the live session last reported holding, else an estimate of the prompt it would send."
        return self._ctx_live or est_tokens(self._prompt()) + est_tokens(self._sp())

    def _sp(self):
        "The briefing plus the tool schemas, for the one channel a managed MCP policy cannot close."
        if self.tool_channel != 'tags': return self.sp   # the caller routed them somewhere itself
        return tag_tools_sp(self.toolspecs, self.sp)

    def _prompt(self):
        "This turn's whole conversation as text. The briefing has a channel of its own."
        return render_prompt(self.hist)

    def _note_usage(self, r):
        "Remember what the turn cost. This is billing volume, not occupancy. See `token_count`."
        self._ctx_tokens = (r.get('usage') or {}).get('total_tokens') or self._ctx_tokens
        return r

    @property
    def in_session(self):
        "Is a Claude Code session live for this chat? Safe on a half-built one: `__del__` reaches here."
        return getattr(self, 'client', None) is not None

    def _recreate_conv(self):
        "Drop the session, so the next turn opens a fresh one and refiles `hist` into it."
        self._disconnect()

    def close(self):
        "End the session and sweep its transcripts. A leaked chat would otherwise leak a `node` process."
        self._disconnect()


