_live_sessions = weakref.WeakSet()
@atexit.register
def _close_sessions():
    "Close every live session, so no `claude` subprocess outlives the interpreter."
    for c in list(_live_sessions):
        try: c._disconnect()
        except Exception: pass

def _connect_err(e):
    "Whether `e` is Claude Code failing to start or connect, which another try may fix, rather than a refusal another try would repeat."
    sdk = claude_agent_sdk
    if isinstance(e, sdk.CLINotFoundError): return False
    return isinstance(e, (sdk.CLIConnectionError, TimeoutError)) or str(e).startswith('Control request timeout: initialize')

def _connect_msg(e, timeout):
    "What a failed connect says."
    return f'Claude Code did not connect within {timeout}s' if isinstance(e, TimeoutError) else f'Claude Code failed while connecting ({e})'

@patch
def _spend(self:ClaudeChat, e=None):
    "Spend this wire call's one retry, if it has one left, the turn is not cancelled, and `e`, if given, is a failure to connect."
    if not self._spare or self._cancel.is_set() or (e is not None and not _connect_err(e)): return False
    self._spare = 0
    return True

@patch
def _connect(self:ClaudeChat):
    "Open or return the live Claude Code session."
    if self.client is not None: return self.client
    past, _ = self._split_turn()
    sid = self._file_sess(past)
    client = claude_agent_sdk.ClaudeSDKClient(options=self._opts(self._sp(), resume=sid, fork=True))
    try: run_sync(asyncio.wait_for(client.connect(), self.timeout))
    except Exception as e:
        if (r := self._refused(e)): raise r from e
        if not self._spend(e): raise
        self._tell(f'{_connect_msg(e, self.timeout)}, so it is being tried once more')
        return self._connect()
    self._session_effort = self.effort
    self.client = client            # `_events` connects before computing the delta, so the watermark
    self._sent = len(past) if sid else 0             # can start at what the resumed session holds
    _live_sessions.add(self)        # tracked so `atexit` can close it: `__del__` is too late
    return client

@patch
def _disconnect(self:ClaudeChat, wait=None):
    "End the session, waiting at most `wait` seconds (default `timeout`), and remove its filed transcripts."
    c = getattr(self, 'client', None)
    self.client, self._sent, self._last_res, self._stale = None, 0, None, False
    self._ctx_live = 0
    if getattr(self, 'cleanup', False): self._sweep()   # a reconnect refiles from `hist` anyway
    if c is None: return
    _live_sessions.discard(self)
    if sys.is_finalizing(): return   # the loop thread is stopped; `run_sync` would never return
    try: run_sync(asyncio.wait_for(c.disconnect(), ifnone(wait, self.timeout)))
    except Exception: pass          # a dead subprocess is already disconnected

@patch
def _delta(self:ClaudeChat):
    "The slice of `hist` the session has not been sent, as one prompt."
    if self._sent < len(self.hist) and self.hist[self._sent] is self._last_res:
        self._sent += 1             # the session wrote this one; sending it back would echo it
    new = self.hist[self._sent:]
    out = self._as_turn(new)
    self._sent = len(self.hist)
    return f'{out}\n\n{CONT_PROMPT}' if new and new[-1].get('role') == 'tool' else out

